def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    total = v1 + v2 + v3

    return {
        "value": total,
        "trace": {
            "v1": v1,
            "v2": v2,
            "v3": v3,
            "total": total,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
